import{A as e}from"./app-modal-qdw6XuZO.js";/* empty css                *//* empty css                     *//* empty css                  */document.getElementById("b1").addEventListener("click",()=>{e.fire({icon:"success",title:"已送出審核",text:"審核通常 1–3 個工作天完成"})});document.getElementById("b2").addEventListener("click",()=>{e.fire({icon:"error",title:"上傳失敗",text:"檔案格式不支援，請改用 JPG / PNG"})});document.getElementById("b3").addEventListener("click",()=>{e.fire({icon:"warning",title:"確定要登出？",showCancelButton:!0,confirmButtonText:"登出",cancelButtonText:"取消"}).then(t=>e.fire({icon:t.isConfirmed?"success":"info",title:t.isConfirmed?"已登出":"已取消"}))});document.getElementById("b4").addEventListener("click",()=>{e.fire({icon:"info",title:"提醒",text:"這篇攻略已被收藏 12 次"})});document.getElementById("b5").addEventListener("click",()=>{e.fire({icon:"question",title:"請輸入暱稱",input:"text",inputPlaceholder:"暱稱"}).then(t=>{t.isConfirmed&&e.fire({icon:"success",title:"你輸入了："+t.value})})});document.getElementById("b6").addEventListener("click",()=>{e.fire({title:"服務條款",input:"checkbox",inputPlaceholder:"我同意服務條款",showCancelButton:!0}).then(t=>{t.isConfirmed&&e.fire({icon:"success",title:"勾選狀態："+t.value})})});document.getElementById("b7").addEventListener("click",()=>{e.fire({toast:!0,icon:"success",title:"已複製邀請碼",timer:1500,showConfirmButton:!1})});document.getElementById("b8").addEventListener("click",()=>{e.fire({imageUrl:"https://picsum.photos/800/500",imageAlt:"範例圖片"})});document.getElementById("b9").addEventListener("click",()=>{e.fire({title:"互動範例",html:'<button id="innerBtn" style="padding:8px 16px;border-radius:999px;border:1px solid #d6e2ec;background:#fff;cursor:pointer;">點我看看</button>',showConfirmButton:!1,showCancelButton:!0,cancelButtonText:"關閉",didOpen:t=>{t.querySelector("#innerBtn").addEventListener("click",()=>{e.fire({icon:"success",title:"didOpen 綁的事件觸發了"})})}})});
